
INSERT INTO email_templates (code, name, subject, body_html, body_text, is_enabled) VALUES
('workflow_external_delay_notice', 'Workflow — External delay notice',
 'Update on your order {{order_id}} — Processing delay',
 '<p>Hi {{customer_name}},</p><p>We wanted to give you a quick update on your <b>{{service_name}}</b> order ({{order_id}}).</p><p>Processing is currently delayed due to: <b>{{reason}}</b>.</p><p>{{customer_note}}</p><p>Our team is actively monitoring this and we will share the next update within 3 working days. You do not need to take any action right now.</p><p>If you have questions, reply to this email or write to <a href="mailto:{{support_email}}">{{support_email}}</a>.</p><p>— {{company_name}} Support<br/>{{support_email}}</p>',
 'Hi {{customer_name}}, your {{service_name}} order ({{order_id}}) is delayed: {{reason}}. We will update you within 3 working days. — {{company_name}} ({{support_email}})',
 true),
('workflow_processing_update_3d', 'Workflow — Processing update (follow-up)',
 'Processing update for order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>This is a quick status update on your {{service_name}} order ({{order_id}}).</p><p>Reason for delay: <b>{{reason}}</b>. We are continuing to follow up and will reach out again as soon as we have progress.</p><p>— {{company_name}} Support<br/><a href="mailto:{{support_email}}">{{support_email}}</a></p>',
 'Hi {{customer_name}}, update on {{order_id}} ({{service_name}}). Reason: {{reason}}. We will reach out again soon. — {{company_name}}',
 true),
('workflow_closure_notice', 'Workflow — Order closure notice',
 'Order {{order_id}} has been closed',
 '<p>Hi {{customer_name}},</p><p>Your order <b>{{order_id}}</b> ({{service_name}}) has been closed.</p><p>Reason: <b>{{reason}}</b>.</p><p>If this was not expected, please reply to this email or write to <a href="mailto:{{support_email}}">{{support_email}}</a> within 7 days.</p><p>— {{company_name}}</p>',
 'Hi {{customer_name}}, your order {{order_id}} ({{service_name}}) has been closed. Reason: {{reason}}. Contact {{support_email}} if you have questions.',
 true),
('workflow_refund_received', 'Workflow — Refund request received',
 'Refund request received — Order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>We have received your refund request for order <b>{{order_id}}</b> ({{service_name}}).</p><p>Our finance team will review it and respond within 3–5 working days.</p><p>— {{company_name}} Support<br/>{{support_email}}</p>',
 'Hi {{customer_name}}, refund request received for {{order_id}}. We will respond within 3–5 working days. — {{company_name}}',
 true),
('workflow_refund_approved', 'Workflow — Refund approved',
 'Refund approved — Order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>Your refund request for order <b>{{order_id}}</b> has been <b>approved</b>.</p><p>Amount: Rs. {{refund_amount}}</p><p>{{admin_notes}}</p><p>The amount will be credited to your original payment method within 5–7 working days.</p><p>— {{company_name}}</p>',
 'Hi {{customer_name}}, refund of Rs. {{refund_amount}} approved for {{order_id}}. Credit in 5–7 working days. — {{company_name}}',
 true),
('workflow_refund_rejected', 'Workflow — Refund rejected',
 'Update on your refund request — Order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>After review, we are unable to approve your refund request for order <b>{{order_id}}</b>.</p><p>{{admin_notes}}</p><p>If you would like to discuss this, please write to <a href="mailto:{{support_email}}">{{support_email}}</a>.</p><p>— {{company_name}}</p>',
 'Hi {{customer_name}}, your refund request for {{order_id}} was not approved. {{admin_notes}} Reach us at {{support_email}}.',
 true),
('workflow_refund_info_needed', 'Workflow — Refund info needed',
 'More information needed for your refund — Order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>We need a bit more information to process your refund for order <b>{{order_id}}</b>.</p><p>{{admin_notes}}</p><p>Please reply to this email at your earliest convenience.</p><p>— {{company_name}} Support<br/>{{support_email}}</p>',
 'Hi {{customer_name}}, we need more info for your refund on {{order_id}}. {{admin_notes}} Please reply. — {{company_name}}',
 true),
('workflow_refund_escalated', 'Workflow — Refund escalated',
 'Your refund request has been escalated — Order {{order_id}}',
 '<p>Hi {{customer_name}},</p><p>Your refund request for order <b>{{order_id}}</b> has been escalated to our senior team for review. We will respond within 3 working days.</p><p>— {{company_name}}</p>',
 'Hi {{customer_name}}, your refund for {{order_id}} has been escalated. We will respond within 3 working days.',
 true)
ON CONFLICT (code) DO UPDATE SET subject = EXCLUDED.subject, body_html = EXCLUDED.body_html, body_text = EXCLUDED.body_text;
